-- 来源：2026-10-16 由真实 Hibernate 启动日志导出（ddl-auto=create）
-- 用途：auth-service 基线迁移，锁定 oauth_accounts / sessions / users 表结构
-- 说明：老库首次接入 Flyway 时以 baseline 方式跳过本文件，新库完整执行
create table oauth_accounts (created_at timestamp(6), id bigint generated by default as identity, user_id bigint not null, provider varchar(16) not null, email varchar(255), provider_user_id varchar(255) not null, primary key (id), unique (provider, provider_user_id));
create table sessions (revoked boolean not null, created_at timestamp(6), expires_at timestamp(6), id bigint generated by default as identity, user_id bigint not null, access_jti varchar(64), ip varchar(64), token_jti varchar(64) not null unique, device_info varchar(255), primary key (id));
create table users (created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), language varchar(16), role varchar(16) not null, status varchar(16) not null, nickname varchar(64) not null, avatar_url varchar(512), email varchar(255) not null unique, password_hash varchar(255), primary key (id));
alter table oauth_accounts add constraint FKn6j2b3ur1fcj3vkodrmqtdxmi foreign key (user_id) references users;
alter table sessions add constraint FKruie73rneumyyd1bgo6qw8vjt foreign key (user_id) references users;
